        /// <summary>
    /// Lookup to display Tariff item stat code and description 
    /// </summary>
    /// <param name="sender">
    /// sender get the form name 
    /// </param>
    /// <param name="e">
    /// e gets the formcontrol 
    /// </param>
    [FormControlEventHandler(formControlStr(EcoResProductDetailsExtended, METInventTable_METTariffItemCodeRecid), FormControlEventType::Lookup)]
    public static void METInventTable_METTariffItemCodeRecid_OnLookup(FormControl sender, FormControlEventArgs e)
    {
        SysReferenceTableLookup tariffItemCodeLookup;
        Query query = new Query();
        QueryBuildDataSource queryBuildDataSource;
       

        tariffItemCodeLookup = SysReferenceTableLookup::newParameters(tableNum(METTariffItemCode), sender);

        // Add the fields to be shown in the lookup form.
        tariffItemCodeLookup.addLookupfield(fieldNum(METTariffItemCode, TariffItem));
        tariffItemCodeLookup.addLookupfield(fieldNum(METTariffItemCode, StatCode));
        tariffItemCodeLookup.addLookupfield(fieldNum(METTariffItemCode, Description));

        queryBuildDataSource = query.addDataSource(tableNum(METTariffItemCode));
        tariffItemCodeLookup.parmQuery(query);

        // Perform the lookup.
        tariffItemCodeLookup.performFormLookup();

        FormControlCancelableSuperEventArgs cancelableArgs = e as FormControlCancelableSuperEventArgs;
        cancelableArgs.CancelSuperCall();
    }

/// <summary>
/// Updated InventTableRecId automatically so that we dont have to select the Item Id Manually.
/// </summary>
/// <param name="sender">
/// sender get the Form Data Source
/// </param>
/// <param name="e">
/// e get Form DataSourceEventArgs
/// </param>
[FormDataSourceEventHandler(formDataSourceStr(EcoResProductDetailsExtended, METInventTable), FormDataSourceEventType::ValidatedWrite),
 SuppressBPWarning("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void METInventTable_OnValidatedWrite(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormRun                 form              = sender.formRun();
    FormDataSource          inventTable_ds    = form.dataSource(formDataSourceStr(EcoResProductDetailsExtended, InventTable)) as FormDataSource;
    FormDataSource          metInventTable_ds = form.dataSource(formDataSourceStr(EcoResProductDetailsExtended, MetInventTable)) as FormDataSource;
    METInventTable          metInventTable    = metInventTable_ds.cursor();
    InventTable             inventTable       = inventTable_ds.cursor();
    
    metInventTable.ItemId = inventTable.ItemId;
    
}

/// <summary>
/// Update Litres Per Pricing Unit when Item Pack is modified
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormControlEventHandler(formControlStr(EcoResProductDetailsExtended, METInventTable_ItemPack), FormControlEventType::Modified),
 SuppressBPWarning("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void METInventTable_ItemPack_OnModified(FormControl sender, FormControlEventArgs e)
{
    METEcoResProductDetailsExtendedEventHandler::updateLitresPricingUnit(sender);
}

/// <summary>
/// Update Litres Per Pricing Unit when Bottle Size/Litres per unit is modified
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormControlEventHandler(formControlStr(EcoResProductDetailsExtended, METInventTable_BottleSize), FormControlEventType::Modified)]
public static void METInventTable_BottleSize_OnModified(FormControl sender, FormControlEventArgs e)
{
    METEcoResProductDetailsExtendedEventHandler::updateLitresPricingUnit(sender);
}

    /// <summary>
    /// Update Litres Per Pricing Unit
    /// </summary>
    /// <param name = "sender"></param>
    public static void updateLitresPricingUnit(FormControl sender)
    {
        FormRun                 form              = sender.formRun();
        FormDataSource          metInventTable_ds = form.dataSource(formDataSourceStr(EcoResProductDetailsExtended, MetInventTable)) as FormDataSource;
        METInventTable          metInventTable    = metInventTable_ds.cursor();

        metInventTable.LitersPerPricingUnit = metInventTable.ItemPack * metInventTable.BottleSize;
    }
